functions.getGridWidth:
function getGridWidth() {
		try {
			var w = window.parent.$("#screensWrapper").width();
			if(w>100)
				return window.parent.$("#screensWrapper").width()-10;
			else
				return $(window).width()-10;
		} catch (e) {
			console.log(e.message);
			return $(window).width()-10;
		}
	}

functions.shortcutKey:
function shortcutKey(){ 		
    	$(document).bind('keydown', function(e) {
    		var keyCode = (e.keyCode) ? e.keyCode : ((e.charCode) ? e.charCode : e.which);
    		if (e.originalEvent.altKey) {
    			// ALT + S     Search                   
    			if (keyCode === 83) {
    				reloadSearchGrid();
    				e.preventDefault();
    				return false;

    			}
    			// ALT + N      Reset                 
    			if (keyCode == 78) {
    				resetAll();
    				e.preventDefault();
    				return false;
    			}
    			// ALT + F    Add New
    			if (keyCode == 70){
    				addnew();
    				e.preventDefault();
    				return false;
    			}

    		}
    	});
    }

functions.openLastTransmitDateDialog:
function openLastTransmitDateDialog(rowId){
			var rowData = jQuery('#transmitLogTable').jqGrid('getRowData', rowId);
			$("#transmitKey").val(rowData.transmitKey);
			$("#clientIdLbl").html(rowData.clientIdTL);
			$("#companyNameLbl").html(rowData.billPartyCodeTL);
			$("#docTypeLbl").html(rowData.intCodeTL);
			$("#modDateLbl").html(rowData.modifiedDate);
			$("#lastTransmitDate").val(rowData.lastTransmitdate);

			$('#lastTransmitDate').datetimepicker({
	  	    	 useCurrent		: true,
	  	    	 format			: 'DD/MM/YYYY hh:mm A',
	  	    	 maxDate		: new Date(),
	  	    	 minDate		: new Date(new Date().getFullYear(), 0, 1)
	  	    });
			$('#lastTransmitDateDialog').modal('show');
		}

