functions.openRequestResponseBody:
function openRequestResponseBody(event, transmitDetKey, rowId){
 			if(transmitDetKey != undefined && transmitDetKey != null && transmitDetKey != "") {

 				var retVal = $.ajax({
 					url : "fetchZohoRequestResponseById",

 					type : "POST",
 					data : {
 						transId : transmitDetKey
 					},
 					dataType : "json",
 					async : false
 				}).responseText;

 				retVal = jQuery.parseJSON(retVal);
 				if(retVal != null && retVal != undefined && retVal.finTransmitDetailDTO != null 
 						&& (retVal.finTransmitDetailDTO.requestJson != null || retVal.finTransmitDetailDTO.responseJson != null)){

 					if(retVal.finTransmitDetailDTO.requestJson != undefined && retVal.finTransmitDetailDTO.requestJson != "")
 						editor.setValue(JSON.stringify(JSON.parse(retVal.finTransmitDetailDTO.requestJson), null, '\t'), -1);
 					else
 						editor.setValue("");

 					 if(retVal.finTransmitDetailDTO.responseJson != undefined && retVal.finTransmitDetailDTO.responseJson != "")
 						editor1.setValue(JSON.stringify(JSON.parse(retVal.finTransmitDetailDTO.responseJson), null, '\t'), -1);
 					else
 						editor1.setValue(""); 
 					var rowData = jQuery("#tallyInterfaceTable").getRowData(rowId);
 					let str = "";
 					if(rowData != undefined && rowData != null && rowData != ""){

 						str = "Document Number : " + rowData.key2;
 					}
 					$("#headLabel").html(str);
 					//VE-16029 E
 					$("#requestResponseDialog").modal("show");
 				}
 				else{
 					window.parent.showAlert('Something Went Wrong');
 					return false;
 				}
 			}
 		}

